starterCode:
LOAD spatial;

-- Bounding-box area per POI category (scaled ×10000, rounded 1dp).
-- Return: category, bbox_area ordered by bbox_area DESC

solution:
LOAD spatial;

SELECT category,
       ROUND(ST_Area(ST_Extent_Agg(ST_Point(lon, lat))) * 10000, 1) AS bbox_area
FROM read_parquet('./data/nyc_pois.parquet')
GROUP BY category
ORDER BY bbox_area DESC;
